257:     targetKm: number;
258:   }) => { ok: true } | { ok: false; message: string };
259:   onRegisterAutoRouteUi?: (ui: PickPopupAutoRouteUi) => void;
260:   /** 예상 시간 계산용 누적 주행 — 없으면 폴백 속도를 쓴다(5A-R2 §4.3) */
261:   getUserMileage?: () => { totalMeters: number | null; totalSec: number | null };
262:   onDirectionPickArmed?: () => void;
263:   onRoutePanelActivated?: () => void;
264:   onPreviewDistanceAutoRouteCircle?: (input: {
265:     start: LngLat;
266:     targetKm: number;
267:   }) => void;
268:   onClearDistanceAutoRouteCircle?: () => void;
269:   onSetRouteProfileOnly?: (p: RouteProfile) => void;
