273:   onClearRoute?: (() => void) | undefined;
274:   onClearAutoRouteClickDebugMarker?: () => void;
275:   initialHasStart: boolean;
276:   initialHasEnd: boolean;
277:   autoRouteSessionActive?: boolean;
278:   autoRouteTargetKm?: number;
279:   autoRouteStatusMessage?: string | null;
280:   closePopup: () => void;
