282:   const {
283:     lngLat,
284:     getWaypointCount,
285:     accessToken,
286:     signal,
287:     onSelectPoint,
288:     initialStart,
289:     routeProfile,
290:     onRouteProfile,
291:     onArmDirectionPick,
292:     onRegisterAutoRouteUi,
293:     getUserMileage,
294:     onDirectionPickArmed,
