.map-view__pick-actions--pin-row .map-view__pick-btn {
  flex: 1 1 0;
  min-width: 0;
  padding: 0.24rem 0.32rem;
  font-size: 0.7rem;
}

/* 지시30 — 패널 접기. hidden 내용이 flex/grid display 에 덮이지 않게 scoped 규칙. */
.map-view__pick [hidden] {
  display: none !important;
}

/* 지시30 — 위치/거리 선택 접이식 패널. 토글 높이를 최소로, 기존 font/컨트롤 크기 유지. */
.map-view__pick-route-panel {
  min-width: 0;
  max-width: 100%;
}

.map-view__pick-route-panel--location {
  margin-top: 0.14rem;
}

.map-view__pick-route-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  padding: 0.14rem 0.2rem;
  border: 0;
  border-radius: 0.35rem;
  background: transparent;
  color: inherit;
  font-size: 0.7rem;
  font-weight: 700;
  line-height: 1.25;
  cursor: pointer;
}

.map-view__pick-route-toggle:hover {
  background: #F1F5F9;
}

.map-view__pick-route-toggle:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 1px;
}

.map-view__pick-route-toggle-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.map-view__pick-route-toggle-caret {
  flex: 0 0 auto;
  font-size: 0.66rem;
  line-height: 1;
  opacity: 0.75;
}

.map-view__pick-route-panel-content {
  min-width: 0;
  max-width: 100%;
}

.map-view__pick-route-panel-content--location .map-view__pick-actions--pin-row {
  margin-top: 0.14rem;
}

.map-view__pick-route-panel--distance {
  margin-top: 0;
}

